// Golden test: the TypeScript engine must reproduce v1 (scripts/recall.py) exactly on 20 recorded states.
// Fixtures were generated by please-hire-me/state/make_golden.py on 2026-10-21 against the same banks/curriculum
// now in supabase/seed. Regenerate only when the algorithm is changed on purpose, in both places.
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import golden from "./__fixtures__/golden.json";
import { buildPlan, mastery, readiness, recommend, secondTrack, thirdSlot, weekNo } from "./engine";
import { TRACKS, type Banks, type Curriculum, type RecallState, type Track } from "./types";

function loadBanks(): { banks: Banks; cur: Curriculum } {
  const seed = (f: string) => JSON.parse(readFileSync(new URL(`../../../supabase/seed/${f}`, import.meta.url), "utf8"));
  const lc = seed("recall-leetcode.json");
  const items = lc.problems.map((p: Record<string, unknown>) => ({
    id: p.slug, title: p.title, difficulty: p.difficulty, topic: (p.category as string) || ((p.topics as string[])?.[0] ?? ""),
    topics: p.topics, lists: p.lists, url: p.url,
  }));
  const bank = (f: string) => { const d = seed(f); return { items: d.items, categories: [...new Set<string>(d.items.map((i: { topic: string }) => i.topic))].sort() }; };
  const banks = {
    leetcode: { items, categories: lc.categories, companies: lc.companies, company_lists: lc.company_lists ?? {} },
    python: bank("recall-python.json"),
    system_design: bank("recall-systemdesign.json"),
    dsa: bank("recall-dsa.json"),
    debugging: bank("recall-debugging.json"),
  } as Banks;
  return { banks, cur: seed("recall-curriculum.json") };
}

const { banks, cur } = loadBanks();
const clone = <T,>(x: T): T => JSON.parse(JSON.stringify(x));

describe("recall engine matches v1 golden outputs", () => {
  for (const g of golden as unknown as Array<{ case: number; today: string; state: RecallState; expected: Record<string, unknown> }>) {
    const st = g.state;
    const e = g.expected as {
      recommend: Record<Track, unknown>; second_track: [string, string]; third_slot: unknown; plan: unknown;
      readiness: Record<Track, number>; mastery_leetcode: Record<string, unknown>; week: number;
    };
    it(`case ${g.case}: week`, () => expect(weekNo(st, cur, g.today)).toBe(e.week));
    it(`case ${g.case}: readiness`, () => { for (const t of TRACKS) expect(readiness(st, banks, t), t).toBe(e.readiness[t]); });
    it(`case ${g.case}: leetcode mastery`, () => expect(mastery(st, banks, "leetcode")).toEqual(e.mastery_leetcode));
    it(`case ${g.case}: recommend per track`, () => { for (const t of TRACKS) expect(recommend(st, banks, cur, t, g.today), t).toEqual(e.recommend[t]); });
    it(`case ${g.case}: second track`, () => expect(secondTrack(st, banks, g.today)).toEqual(e.second_track));
    it(`case ${g.case}: third slot`, () => expect(thirdSlot(st, cur, g.today)).toEqual(e.third_slot));
    it(`case ${g.case}: plan`, () => expect(buildPlan(clone(st), banks, cur, g.today)).toEqual(e.plan));
  }
});
